import type { Seed } from './roadmap-build';

// "Security" learning path — 120 questions (15 levels × 8), easiest → hardest:
// security fundamentals, authentication & authorization, password hashing,
// sessions/JWT, HTTPS/TLS, injection, XSS, CSRF, the OWASP Top 10, secrets
// management, secure headers, supply chain, privacy and threat modeling.
// (ids rm-security-1 … rm-security-120, 8 per level).
export const securitySeeds: Seed[] = [
  // Level 1 — Security Fundamentals
  { q: 'A security review asks whether data stays secret, remains accurate, and is reachable when authorized users need it. Which model groups those goals?', opts: ['Zero trust', 'The CIA triad', 'Defense in depth', 'The shared-responsibility model'], a: 1, e: 'The CIA triad names the goals: confidentiality (no unauthorized disclosure), integrity (no unauthorized change) and availability (usable when authorized users need it). Zero trust and defense in depth are strategies for reaching those goals, not the goals. The shared-responsibility model divides duties between a cloud provider and its customer.', tags: ['Security', 'fundamentals'], intro: 'The scenario lists three properties, not three practices. Ask which option names goals rather than ways of reaching them.' },
  { q: 'A report generator needs read access to one storage bucket. Which permission follows least privilege?', opts: ['Administrator access so future features do not need changes', 'Read access to that bucket and no unrelated permissions', 'Write access to every bucket in the same cloud account', 'The same shared credentials used by the deployment system'], a: 1, e: 'Least privilege grants only the action and the resource scope the task requires: read, on that one bucket. Administrator access or write access to every bucket turns one compromised report generator into full control of the account. Reusing the deployment system\'s credentials is worse still: it merges two blast radii and makes the audit log unable to say which system acted.', intro: 'Ask what an attacker could do with the report generator\'s credentials the day after it is compromised.', tags: ['Security', 'least-privilege'] },
  { q: 'An attacker steals a valid password, but MFA and a per-request authorization check still block access to sensitive records. Which principle is at work?', opts: ['A single strong perimeter control', 'Defense in depth through independent security layers', 'Security by keeping the authentication design secret', 'Availability through automatic failover'], a: 1, e: 'Two further controls had to fail as well: the MFA challenge and the per-request authorization check. One stolen credential therefore bought the attacker nothing. A single strong perimeter control is the opposite arrangement, where everything behind the wall is exposed the moment the wall fails. Keeping the design secret is obscurity rather than a control, and failover addresses availability, not this attack.', intro: 'The password fell and the account still held. What does that tell you about how many barriers stood behind it?', tags: ['Security', 'defense-in-depth'] },
  { q: 'A signed-in user submits a profile name that will later appear in HTML. What is the sound input-handling approach?', opts: ['Trust it because authentication identifies the sender', 'Validate it for the business rules and escape it for the HTML output context', 'Sanitize it only in the browser before sending the request', 'Store it unchanged and remove suspicious characters when reading any database row'], a: 1, e: 'Authentication does not make input safe. Validate on the server, and encode or escape data for the context where it is used; generic character stripping is not a complete defense.', intro: 'The same string has to be valid business data now and safe HTML later. Are those the same job?', tags: ['Security', 'input'] },
  { q: 'A team removes an unused public admin endpoint and disables an unnecessary network port. What did it reduce?', opts: ['The blast radius after an administrator account is compromised', 'The attack surface', 'The recovery point objective for stored data', 'The entropy of its authentication tokens'], a: 1, e: 'Deleting a reachable endpoint and closing a port both remove places an attacker can interact with the system, and that set of reachable interfaces, inputs and services is the attack surface. Blast radius is a different measure: how much damage follows once a compromise has happened. Recovery point objective is a backup target, and token entropy is a property of the tokens themselves.', intro: 'Neither change altered anyone\'s permissions. Both removed something an outsider could reach at all.', tags: ['Security', 'attack-surface'] },
  { q: 'An API is considered safe only because its undocumented URL is hard to guess. What is the main weakness?', opts: ['The URL should be encrypted rather than merely undocumented', 'Secrecy of the design is standing in for authentication and authorization', 'A less descriptive HTTP method would make the endpoint harder to find', 'Access control only holds while the source repository stays private'], a: 1, e: 'Nothing checks who is calling: the only barrier is that the address is hard to guess, and addresses leak through server logs, Referer headers, browser history, proxies and shared links. Kerckhoffs\'s principle is the standard to apply here — the design may become public as long as authentication and authorization still hold. Encrypting the URL, changing the HTTP method or keeping the repository private all leave the endpoint open to anyone who has the address.', intro: 'Assume the attacker already has the URL. Ask what is left protecting the endpoint.', tags: ['Security', 'obscurity'] },
  { q: 'An authorization service times out while an API checks whether a user may delete a record. How should the API fail?', opts: ['Allow the request because the user might have permission', 'Deny the operation and return a controlled error', 'Show the authorization stack trace so the user can retry correctly', 'Skip only the resource-level check but keep the role check'], a: 1, e: 'Failing securely means choosing the safe state when a control cannot make a decision. For authorization, that normally means denying the action without exposing internals.', intro: 'The check did not say no; it said nothing at all. Which outcome is safe when the answer is unknown?', tags: ['Security', 'fail-secure'] },
  { q: 'A request comes from a machine on the company network with a valid device certificate. What would a zero-trust design still do?', opts: ['Treat the network location as enough proof for every resource', 'Authenticate the request and authorize it for the specific resource', 'Skip identity checks but log the source IP for later review', 'Grant the device the same access as its most privileged user'], a: 1, e: 'Zero trust does not make network location a blanket trust signal. Each request still needs verified identity, policy, and appropriate context.', intro: 'A device certificate says which machine is calling. It does not say who is calling or what they may reach.', tags: ['Security', 'zero-trust'] },

  // Level 2 — Authentication
  { q: 'Authentication answers the question:', opts: ['What are you allowed to do?', 'Who are you, and can you prove it?', 'Where is the request coming from?', 'How long may the session last?'], a: 1, e: 'Authentication establishes and verifies identity; authorization is the separate, later step that decides what that verified identity may do. Confusing the two produces systems that check a login once and then never check permissions per action. Request origin and session lifetime are properties of the connection and the session, not claims about who is calling.', intro: 'One of these has to be settled before any permission can be looked up. Which one comes first?', tags: ['AuthN', 'basics'] },
  { q: 'Multi-factor authentication (MFA) combines:', opts: ['Two knowledge factors, such as a password and a security question', 'Factors from two different categories, such as knowledge and possession', 'Two accounts that belong to the same person', 'One factor checked twice within the same login'], a: 1, e: 'MFA requires factors from different categories — something you know, something you have, something you are — so compromising one does not deliver the others. A password plus a security question is two knowledge factors: a single phishing page or a single breach dump can yield both. Repeating one factor adds a step to the login without adding independent evidence of identity.', intro: 'Ask what one phishing page could capture in a single visit, and what it could not.', tags: ['AuthN', 'mfa'] },
  { q: 'A password is an example of which authentication factor?', opts: ['Something you have', 'Something you know', 'Something you are', 'Somewhere you are'], a: 1, e: 'A password is knowledge: it is memorized, so it can be phished, guessed, reused or leaked in a breach dump without anything physical changing hands. Possession factors are things you carry, such as a security key or a phone running an authenticator app, and inherence factors are body measurements such as a fingerprint. Location is sometimes used as an extra risk signal but is not one of the three standard categories, which is why it cannot stand in as a second factor.', intro: 'Classify by what the user must supply, not by the device they happen to supply it from.', tags: ['AuthN', 'factors'] },
  { q: 'OAuth 2.0 is primarily a framework for:', opts: ['Authentication: proving to an application who the end user is', 'Delegated authorization: granting an application limited access on your behalf', 'Encryption of the data an application exchanges with an API', 'Storage of user passwords in a form an application can verify'], a: 1, e: 'OAuth 2.0 is an authorization framework: the user grants a client scoped, revocable access to a resource without sharing credentials with it. It deliberately says nothing about proving who the end user is; OpenID Connect adds that on top with ID tokens, and treating a bare OAuth access token as proof of login is a well-known and exploitable shortcut. Transport encryption and password storage are separate concerns that OAuth assumes are already handled.', intro: 'Think about what a consent screen asks you to approve when you connect a third-party app to an account you already have.', tags: ['AuthN', 'oauth'] },
  { q: 'OpenID Connect (OIDC) adds to OAuth:', opts: ['A standard way to encrypt tokens end to end', 'An identity layer that returns a verifiable ID token about the user', 'A replacement for OAuth 2.0 using entirely different flows', 'A directory service that stores the user accounts themselves'], a: 1, e: 'OpenID Connect is a thin identity layer over OAuth 2.0: alongside the access token the provider issues an ID token, a signed JWT of claims about the authenticated user that the client verifies. It reuses OAuth\'s flows rather than replacing them, and it is not a user store - the identity provider keeps the accounts. Token encryption is optional and independent of what OIDC adds.', intro: 'Look at what the client receives at the end of the flow, in addition to the access token.', tags: ['AuthN', 'oidc'] },
  { q: 'Account lockout/throttling after repeated failed logins defends against:', opts: ['XSS', 'Brute-force password guessing', 'CSRF', 'SQL injection'], a: 1, e: 'Throttling and lockout limit how many guesses can be made against an account in a given time, and repeated attempts are exactly what online password guessing depends on. XSS, CSRF and SQL injection each succeed on one well-formed request, so a failed-login counter does nothing against them. Prefer throttling with increasing delays over hard lockout: a lockout any anonymous request can trigger becomes a denial-of-service tool against real users, which is why OWASP ties the counter to the account and warns about exactly this.', intro: 'Ask what a per-account failure counter can actually measure, then check which of these four attacks would show up in it.', tags: ['AuthN', 'brute-force'] },
  { q: 'Single sign-on (SSO) lets users:', opts: ['Authenticate once with a central identity provider and reach many applications', 'Keep a separate stored password inside each application they use', 'Reach applications without authenticating at any point', 'Turn off multi-factor authentication for connected applications'], a: 0, e: 'SSO moves authentication to a central identity provider: the user proves identity once and each connected application trusts an assertion or token from that provider instead of holding its own password. Each application still authorizes separately, so SSO is not a permission grant. The trade-off is concentration - one compromised provider session reaches every connected application, which is why SSO is normally paired with MFA and a short session lifetime at the provider.', intro: 'Nothing here removes the login step. Ask where that step happens and what each application trusts instead of its own password.', tags: ['AuthN', 'sso'] },
  { q: 'Generic login error messages ("invalid email or password") help because:', opts: ['They keep the failure reason out of the server logs', 'They do not reveal whether an account with that email exists', 'They make the login request complete faster', 'They remove the need for rate limiting on the login endpoint'], a: 1, e: 'Because the same message covers both an unknown account and a wrong password, an attacker submitting an email with any password learns nothing about whether that account exists, so the login form cannot be used to build a list of valid accounts. The reason still belongs in the server log; it just does not belong in the response. The message does not speed anything up, and the endpoint still needs throttling - a generic error closes the enumeration channel, not the guessing one. Registration, password reset and response timing leak the same fact if they are not aligned.', intro: 'One message covers two very different failures. What would a separate message for each one tell an attacker?', tags: ['AuthN', 'enumeration'] },

  // Level 3 — Authorization
  { q: 'Authorization determines:', opts: ['Whether the caller\'s identity claim is genuine', 'Whether this identity may perform this action on this resource', 'Which identity provider issued the caller\'s session', 'How long the caller\'s session remains valid'], a: 1, e: 'Authorization runs after identity is settled and answers a per-action, per-resource question: may this identity do this, to this object, now. That framing matters because a check that only asks is this user an admin misses object-level ownership, the gap behind most broken access control findings. Verifying the identity claim is authentication, and the issuing provider and session lifetime are session properties rather than permission decisions.', intro: 'Ask what still has to be decided when a known user requests a document that belongs to someone else.', tags: ['AuthZ', 'basics'] },
  { q: 'A publishing system assigns permissions to editor, reviewer, and administrator roles, then assigns users to those roles. Which access-control model is this?', opts: ['Attribute-based access control using request context only', 'Role-based access control (RBAC)', 'Discretionary access controlled separately by each document owner', 'Network access control based on source address'], a: 1, e: 'RBAC assigns permissions to named roles and then assigns users to those roles. It is useful when job functions map cleanly to permission sets.', intro: 'Permissions are attached to something, and users are attached to that same thing. Name the layer in the middle.', tags: ['AuthZ', 'rbac'] },
  { q: 'A "broken access control" bug is when:', opts: ['Passwords are weak', 'Users can access resources/actions they shouldn’t be allowed to', 'TLS is misconfigured', 'Logs are missing'], a: 1, e: 'Broken access control means the server lets an identity perform an action or read data outside its permissions: changing an id in a URL, calling an endpoint the UI merely hides, or setting a field the role may not set. It is A01 in the OWASP Top 10:2025, the same position it held in 2021. Weak passwords are an authentication failure, TLS misconfiguration is a cryptographic or configuration failure, and missing logs are a detection failure - each is its own category.', intro: 'All four describe real security failures. Which one is specifically about permissions being wrong?', tags: ['AuthZ', 'broken-access'] },
  { q: 'An IDOR (Insecure Direct Object Reference) happens when:', opts: ['The id in the URL is sequential and therefore easy to guess', 'The server returns an object by id without checking who owns it', 'The client caches another user\'s response and replays it later', 'The id travels in the URL instead of the request body'], a: 1, e: 'IDOR is a missing object-level authorization check: the handler loads the record named by the id and returns it without asking whether the caller owns it. Guessable or visible ids only make the flaw easier to find - swapping sequential ids for UUIDs hides the door without locking it, and the ownership check is still the fix. Where the id travels and whether a response is cached do not change who the server decides may read the object.', intro: 'Ask what still goes wrong when the ids are random UUIDs that an attacker has legitimately seen once.', tags: ['AuthZ', 'idor'] },
  { q: 'Authorization checks must be enforced:', opts: ['Once at login, then cached in the session for its duration', 'On the server, for every request that touches a protected resource', 'In the client before the request is sent, to save a round trip', 'At the network edge, by restricting which address ranges may connect'], a: 1, e: 'Each protected request needs its own server-side decision. A permission settled once at login goes stale the moment a role is revoked or a record changes owner, and nothing stops the client from sending a different request afterwards. A client-side check is a user-interface convenience, because the request can be sent without the client at all. Restricting address ranges controls where a request comes from, not what the identity behind it may do.', intro: 'Picture a role revoked five minutes after login, and a request that never went through your interface.', tags: ['AuthZ', 'server-side'] },
  { q: 'Hiding an admin button in the UI but not checking permission on the server is:', opts: ['Secure, because the endpoint cannot be reached without the button', 'Insecure, because the endpoint can still be called directly', 'Secure once the button is stripped from the production bundle', 'Insecure only for users able to read the JavaScript bundle'], a: 1, e: 'The endpoint accepts whatever arrives at it, and the browser is outside the trust boundary: curl, a proxy or an edited bundle all send the same request. Stripping the button from the production build changes nothing for the same reason. Nor is the exposure limited to people who read the bundle - endpoints turn up through API documentation, error messages and directory guessing. Hiding controls is good interface design and never an access control.', intro: 'The button is one way to reach the endpoint. Ask whether it is the only way.', tags: ['AuthZ', 'client-vs-server'] },
  { q: 'Deny-by-default authorization means:', opts: ['Everything is allowed unless some rule blocks it', 'Nothing is allowed unless some rule permits it', 'Each resource owner decides access case by case', 'Administrators bypass the rules and everyone else is blocked'], a: 1, e: 'Deny by default means a missing rule denies, which matters most for the case nobody thought about: a new endpoint, a new field, a newly added bucket. Under allow by default that same omission silently exposes the resource and is usually discovered only when someone reports it. Owner-decided access is discretionary access control, a different model, and letting administrators bypass the rules describes an exception, not a default.', intro: 'Picture a resource nobody has written a rule for yet. Which posture leaves it exposed?', tags: ['AuthZ', 'default-deny'] },
  { q: 'Attribute/policy-based access control (ABAC) decides access using:', opts: ['A single role name assigned to the user', 'Attributes of the user, the resource and the context, evaluated by a policy', 'The user\'s network address alone, ignoring other attributes', 'The order in which the permissions were originally granted'], a: 1, e: 'ABAC evaluates a policy over attributes: who the subject is, which resource is being touched, and the surrounding context such as ownership, time or device posture. That expresses rules like only the owning department, and only during business hours, which RBAC can approximate only by multiplying roles. A single role name is precisely the RBAC case, source address alone is a network control, and grant order is not an input to either model.', intro: 'A role is one label. What does a rule need when the decision depends on the record itself and on the moment?', tags: ['AuthZ', 'abac'] },

  // Level 4 — Passwords & Hashing
  { q: 'Passwords should be stored:', opts: ['In plaintext', 'As salted hashes using a slow password-hashing algorithm', 'Encrypted with a shared key', 'In the source code'], a: 1, e: 'Store a verifier rather than the password: a salted, deliberately slow password hashing function. Current OWASP guidance names Argon2id as the first choice, scrypt where Argon2id is unavailable, PBKDF2 with HMAC-SHA-256 where FIPS-140 compliance is required, and bcrypt for legacy systems only. Encrypting under a shared key is reversible by design, so a single leaked key returns every password in plaintext - that is key management, not password storage. Plaintext and hard-coded credentials expose everything the moment the database or the repository leaks.', intro: 'The store has to survive being copied. Which form is still useless to whoever copied it?', tags: ['Passwords', 'hashing'] },
  { q: 'A "salt" is:', opts: ['A secret key', 'A unique random value added per password before hashing', 'A type of cipher', 'A session token'], a: 1, e: 'A salt is a unique random value mixed into each password before hashing, so two users with the same password store different hashes and no single precomputed table covers both. It does not have to be secret and is normally stored next to the hash; a secret value held elsewhere is a pepper, not a salt. In practice Argon2id, scrypt and bcrypt generate and encode the salt themselves, so application code rarely handles it directly.', intro: 'Rainbow tables are computed once and reused against every database. Ask what would make one table useless here.', tags: ['Passwords', 'salt'] },
  { q: 'Why use a deliberately slow hash (bcrypt/Argon2) for passwords?', opts: ['To slow the login request enough that users notice the check', 'To make each guess against a leaked hash expensive', 'To reduce the CPU the server spends on each login', 'To shorten the stored value so the database column is smaller'], a: 1, e: 'The work factor is tuned so one login costs a few hundred milliseconds while an offline attacker, who must repeat the whole computation for every candidate password, pays that cost on every guess. Measured on Node 22, scrypt at N=16384 takes about 32 ms per hash against about 1.6 microseconds for one SHA-256 - roughly a twenty-thousand-fold difference per attempt. The slowness is the feature: it is spent, not saved, and it does nothing for storage size.', intro: 'The server pays this cost once per login. Ask who pays it billions of times.', tags: ['Passwords', 'slow-hash'] },
  { q: 'Using a fast hash like MD5/SHA-256 (alone) for passwords is:', opts: ['Acceptable as long as every password gets a unique salt', 'Unsafe, because they are fast and carry no tunable work factor', 'Equivalent to bcrypt once the hash is stored with its salt', 'Required whenever the database column has a fixed width'], a: 1, e: 'Salting stops precomputation but does nothing about speed, and speed is what breaks passwords: commodity hardware tries salted SHA-256 candidates by the billion per second, so a targeted offline attack still succeeds. A password hash needs a tunable cost as well as a salt. Current OWASP guidance is Argon2id first, scrypt where Argon2id is unavailable, PBKDF2 with HMAC-SHA-256 for FIPS-140 compliance, and bcrypt only for legacy systems. Column width is not a security property.', intro: 'The attacker who has the hashes has the salts too. Ask what the salt is still buying at that point.', tags: ['Passwords', 'mistakes'] },
  { q: 'A "rainbow table" attack is defeated mainly by:', opts: ['Longer usernames', 'Per-password salting', 'Faster hashing', 'Plaintext storage'], a: 1, e: 'Unique salts make precomputed hash tables (rainbow tables) useless, since each password hashes uniquely.', tags: ['Passwords', 'rainbow'] },
  { q: 'Modern password guidance favors:', opts: ['Frequent forced resets and strict composition rules', 'Longer passphrases and checks against known-breached lists', 'Short passwords with mandatory symbols and digits', 'Blocking password managers so passwords are typed by hand'], a: 1, e: 'Current guidance - NIST SP 800-63B, restated by OWASP - favors length over composition: allow long passphrases, impose no upper-case, digit or symbol requirement, block passwords found in breach corpora, and drop scheduled expiry, which mostly produces predictable increments. OWASP treats passwords shorter than 15 characters as weak without MFA and shorter than 8 with it, and asks for a maximum of at least 64 so passphrases fit. Forced resets with complexity rules are the practice this replaced, and password managers are encouraged rather than blocked.', intro: 'Two of these describe what password rules used to require. Which one describes what actually resists guessing?', tags: ['Passwords', 'policy'] },
  { q: 'A "pepper" differs from a salt by being:', opts: ['A random value stored next to each password hash', 'A secret held outside the database, in a secrets vault or an HSM', 'A public value published with the hash so it can be verified', 'A per-user value regenerated on every password change'], a: 1, e: 'A pepper is a single secret applied to every password and deliberately kept out of the password database, so a database-only leak leaves the attacker missing an input. OWASP puts it in a secrets vault or an HSM rather than a config file that ends up in the same backup or repository, and applies it as an HMAC before or after the password hash. Salts are the opposite on every axis: per-password, random, not secret, stored with the hash. The pepper buys nothing once the application host itself is compromised, which is why it is an extra layer and not a substitute for a strong password hash.', intro: 'A pepper is one value shared by every account. Ask what that makes possible that a per-password value could not.', tags: ['Passwords', 'pepper'] },
  { q: 'Credential stuffing exploits the fact that:', opts: ['Password hashes can be computed quickly on modern hardware', 'People reuse passwords, so credentials leaked elsewhere work here too', 'Session cookies remain valid after the password is changed', 'Login endpoints often return a distinct error for unknown accounts'], a: 1, e: 'Credential stuffing replays username and password pairs harvested from another site\'s breach: nothing is cracked and nothing is guessed, because the passwords are already correct wherever the user reused them. Fast hashes matter to offline cracking, distinct error messages enable account enumeration, and sessions surviving a password change is a session-management bug - three different attacks. The defenses that apply here are MFA, checking submitted passwords against breach corpora at sign-in, and rate limiting by source rather than by account, since each account sees only one attempt.', intro: 'The attacker already holds valid passwords. Ask why they would work on a site that never leaked anything.', tags: ['Passwords', 'credential-stuffing'] },

  // Level 5 — Sessions & Tokens (JWT)
  { q: 'After a successful password check, what should later requests normally present so the password is not sent again?', opts: ['Only the client IP address', 'A session identifier or an appropriate authentication token', 'The raw password in a custom request header', 'The numeric user id with no integrity protection'], a: 1, e: 'A session id or token represents the authenticated session. The server must validate it; an IP or editable user id is not proof of identity.', intro: 'Test each option by asking whether an attacker could produce it for someone else\'s account.', tags: ['Sessions', 'basics'] },
  { q: 'A session cookie should typically be set with:', opts: ['No attributes, so the cookie works in every context', 'HttpOnly, Secure and SameSite', 'Secure alone, since HTTPS already protects the value in transit', 'HttpOnly alone, since that is what stops the token being stolen'], a: 1, e: 'The three attributes address different threats and none substitutes for another: HttpOnly keeps the value out of document.cookie so injected script cannot read it, Secure stops the cookie being sent over plain HTTP, and SameSite limits when the browser attaches it to cross-site requests. Secure alone leaves the cookie readable by script; HttpOnly alone still lets it travel over HTTP and ride cross-site requests. Add the __Host- prefix and a CSRF token as well - OWASP treats SameSite as a defense-in-depth control that does not replace a proper CSRF defense in most deployments.', intro: 'Work out what each attribute actually forbids, then check that list against the ways a session cookie is stolen or misused.', tags: ['Sessions', 'cookies'] },
  { q: 'The HttpOnly cookie flag prevents:', opts: ['The cookie from being sent over plain HTTP', 'Script in the page from reading the cookie value', 'Cross-site requests from including the cookie', 'The cookie from being attached to fetch or XHR calls'], a: 1, e: 'HttpOnly removes the cookie from document.cookie, so injected script cannot read the value and send it elsewhere. It does not stop the cookie being sent: an HttpOnly cookie still rides along on fetch and XMLHttpRequest calls the page makes, so an XSS payload can act as the user from inside the page - it simply cannot carry the session away. Keeping the cookie off plain HTTP is what Secure does, and limiting cross-site sending is what SameSite does.', intro: 'Reading a cookie and sending a cookie are different operations. Decide which one the flag touches.', tags: ['Sessions', 'httponly'] },
  { q: 'A JWT (JSON Web Token) is:', opts: ['Always encrypted', 'A signed token carrying claims that the server can verify without a DB lookup', 'A password', 'A cookie flag'], a: 1, e: 'A JWT is a signed (not necessarily encrypted) token of claims; the signature lets the server trust it statelessly.', tags: ['Tokens', 'jwt'] },
  { q: 'A common JWT pitfall is:', opts: ['Verifying the signature', 'Putting sensitive data in the (base64url, readable) payload thinking it’s hidden', 'Short expiry', 'Using HTTPS'], a: 1, e: 'The header and payload are base64url-encoded, not encrypted: anyone who holds the token, intercepts it, or finds it in a log can decode the claims without any key. The signature protects integrity, not confidentiality - it detects tampering and hides nothing. Keep personal data and secrets out of the payload, or use an encrypted JWT (JWE) when the claims themselves must stay private. Verifying signatures, setting a short expiry and using HTTPS are all things to do, not pitfalls.', intro: 'Paste the middle segment of a token into any decoder. Ask who needed a key to do that.', tags: ['Tokens', 'jwt-pitfall'] },
  { q: 'Short token lifetimes plus refresh tokens help by:', opts: ['Removing the need to authenticate the user again', 'Limiting the window in which a stolen access token is useful', 'Making access tokens impossible to steal in the first place', 'Letting the server invalidate any issued token immediately'], a: 1, e: 'A short-lived access token bounds the damage: a stolen one stops working within minutes, and the refresh token that renews it lives at the authorization server, where it can be revoked. It neither prevents theft nor delivers instant revocation - between theft and expiry the token still works. RFC 9700, the OAuth 2.0 Security Best Current Practice published in January 2025, therefore requires refresh tokens for public clients to be sender-constrained or rotated, and recommends sender-constraining access tokens with mutual TLS or DPoP so a leaked token is unusable by anyone else.', intro: 'Ask what happens if nobody ever learns the token was stolen.', tags: ['Tokens', 'expiry'] },
  { q: 'A downside of stateless JWTs is that:', opts: ['They cannot carry user claims without a server lookup', 'They cannot be invalidated before exp without adding server state', 'They require a database read on every request', 'They can only be issued by the authorization server'], a: 1, e: 'Statelessness is the point of the design and also its cost: with nothing recorded server-side, a logout, a password change or a disabled account cannot invalidate a token already in circulation, and it stays good until exp. Getting revocation back means putting state back - a denylist checked on each request, a token version stamped into the claims, or short expiry paired with revocable refresh tokens - which trades away the lookup-free property. Carrying claims is exactly what a JWT does, and it is the opaque session identifier, not the JWT, that needs a lookup every time.', intro: 'Check each option against how verification actually works: a signature check with a key, and nothing else.', tags: ['Tokens', 'revocation'] },
  { q: 'Storing a JWT in localStorage (vs an HttpOnly cookie) increases risk of:', opts: ['Cross-site request forgery, since the browser attaches it automatically', 'Theft by injected script, since JavaScript can read localStorage', 'Slower requests, since localStorage is read synchronously', 'Certificate errors, since localStorage is not covered by TLS'], a: 1, e: 'Anything in localStorage is readable by any script on the origin, so one XSS flaw exfiltrates the token, while an HttpOnly cookie is never exposed to document.cookie. That is a real improvement and not a cure: the cookie is still attached to requests the injected script makes, so XSS can act as the user either way, and moving the token into a cookie brings CSRF into scope - which is what SameSite plus a CSRF token is for. The decision is between different failure modes, not between insecure and secure.', intro: 'One of these risks belongs to the cookie design rather than the localStorage design. Sort out which.', tags: ['Tokens', 'storage'] },

  // Level 6 — HTTPS & TLS
  { q: 'What security properties does a correctly validated HTTPS connection provide for data in transit?', opts: ['Confidentiality only, without tamper detection or server identity', 'Encryption, integrity, and server authentication through TLS', 'Authorization to every endpoint on the connected server', 'Protection after plaintext data has been stored by either endpoint'], a: 1, e: 'TLS encrypts traffic, detects modification, and authenticates the server certificate. Application authorization and security of stored data remain separate concerns.', intro: 'Ask what TLS can promise about bytes on the wire, and exactly where that promise stops.', tags: ['TLS', 'https'] },
  { q: 'Without HTTPS, data sent over the network can be:', opts: ['Never seen', 'Read or modified by anyone on the path (man-in-the-middle)', 'Automatically encrypted', 'Compressed only'], a: 1, e: 'Plain HTTP is readable and modifiable in transit, enabling eavesdropping and man-in-the-middle attacks.', tags: ['TLS', 'mitm'] },
  { q: 'A TLS certificate is used to:', opts: ['Encrypt the connection without involving any third party', 'Bind a public key to a host name so clients can verify who they reached', 'Hold a copy of the site\'s private key for clients to download', 'Vouch that the site handles the data it receives responsibly'], a: 1, e: 'A certificate binds a public key to a host name and is signed by a CA the client already trusts, so completing the handshake tells the client it is talking to whoever holds that name\'s private key rather than to an interceptor. The private key never leaves the server, and the certificate does not itself encrypt anything - the handshake derives session keys, and the certificate is what ties those keys to the right party. It says nothing about whether the operator behind the name is honest or careful with data, which is the padlock misconception worth unlearning.', intro: 'The certificate is public and every visitor gets a copy. Ask what a public document can prove.', tags: ['TLS', 'certificates'] },
  { q: 'A certificate authority (CA) is:', opts: ['A registry that publishes the private keys of participating sites', 'A party the browser already trusts, whose signature makes a site certificate acceptable', 'A service that performs the encryption on the site\'s behalf', 'An index of revoked certificates that each browser maintains itself'], a: 1, e: 'Browsers and operating systems ship with a set of root CAs trusted in advance; a site certificate is accepted because it chains up to one of those roots, which is what lets a client verify a name it has never encountered. CAs sign certificates - they do not encrypt traffic and never hold a site\'s private key. Withdrawing a certificate that has already been issued is a separate mechanism (CRLs, OCSP, short lifetimes), not what makes a CA a CA.', intro: 'Ask why an attacker cannot simply generate a certificate for this host name themselves.', tags: ['TLS', 'ca'] },
  { q: 'HSTS (HTTP Strict Transport Security) tells browsers to:', opts: ['Refuse to load the site over HTTP for a stated period', 'Prefer HTTPS but fall back to HTTP when the handshake fails', 'Cache the site\'s certificate so later handshakes can be skipped', 'Add the Secure attribute to every cookie the site sets'], a: 0, e: 'HSTS tells the browser that for max-age seconds this host is HTTPS-only: HTTP URLs are rewritten before the request leaves, and a certificate error becomes a hard failure the user cannot click through. There is no fallback, which is the point - a downgrade is precisely what an attacker on the path is after. The gap is the first visit: the browser only learns the rule after one successful HTTPS response, and the preload list exists to close exactly that window. It has nothing to do with certificate caching or cookie attributes.', intro: 'Ask what the browser should do with an http:// link to this site after it has seen the header.', tags: ['TLS', 'hsts'] },
  { q: 'TLS provides "encryption in transit." Sensitive data also needs:', opts: ['Nothing further, since TLS covers the data\'s whole lifecycle', 'Its own protection where it is stored: access control, encryption and backup handling', 'The same TLS certificate applied to the database connection', 'A longer max-age on the HSTS header covering the storage host'], a: 1, e: 'TLS terminates at the endpoints: once bytes are written to a disk, a backup, a log or an export, the connection that carried them is irrelevant. Data at rest needs its own controls - access control on the store, encryption of the volume or column, key management, and the same discipline applied to backups and exports, which are the copies people forget to include in scope. Encrypting the database connection is still protection in transit, just on a different hop.', intro: 'TLS protects the data while it is moving. Ask what is protecting it once it stops.', tags: ['TLS', 'at-rest'] },
  { q: 'An HTTPS page references a script and an image over plain HTTP. What do current browsers do, and why?', opts: ['Both load normally, since only the page\'s own HTML is protected', 'The script is blocked and the image is upgraded to HTTPS, because an HTTP subresource can be altered on the path', 'Both are blocked, because an HTTPS page may never issue an HTTP request', 'Both load but are marked insecure, leaving the decision to the user'], a: 1, e: 'An HTTP subresource can be read and rewritten by anyone on the path, and a rewritten script owns the page, so browsers block mixed scripts, stylesheets, iframes and fetch requests outright. Images, audio and video are auto-upgraded to HTTPS instead, and blocked if the upgrade fails or the URL names a bare IP address. The everyday consequence today is therefore a broken page rather than a silent compromise - but the reason for the block has not changed, and serving every subresource over HTTPS is still the fix.', intro: 'Ask what someone on the path could change in each resource, and what that change would let them do.', tags: ['TLS', 'mixed-content'] },
  { q: 'Modern TLS configuration should:', opts: ['Keep TLS 1.0 and 1.1 enabled so older clients can still connect', 'Serve TLS 1.2 and 1.3 only, with weak cipher suites disabled', 'Disable certificate validation to avoid handshake failures', 'Use a self-signed certificate to avoid depending on a CA'], a: 1, e: 'Current practice is TLS 1.3 with TLS 1.2 retained for compatibility, and SSLv3, TLS 1.0 and TLS 1.1 turned off along with weak cipher suites: RFC 8996 formally deprecates TLS 1.0 and 1.1 and every current browser has dropped them, so leaving them enabled surrenders a security property without reaching any client that still exists. Disabling certificate validation removes server authentication, leaving encryption to an unknown party. A self-signed certificate in production teaches users to click through the very warning meant to stop an interception.', intro: 'Check which protocol versions current standards still allow, not which ones a server happens to support.', tags: ['TLS', 'config'] },

  // Level 7 — Injection (SQLi)
  { q: 'SQL injection occurs when:', opts: ['The database account has more privileges than the application needs', 'Untrusted input is concatenated into a query, so it can change the query\'s structure', 'The query returns more rows than the application expects to display', 'The database error message reveals table and column names'], a: 1, e: 'SQL injection is a parsing problem: because the input is concatenated into the statement before the database parses it, a quote and a keyword in the input become syntax rather than a value, and the statement executed is not the one the developer wrote. An over-privileged database account and a verbose error message make the consequences worse and the flaw easier to find, but neither creates it. Returning too many rows is a logic bug, not an injection.', intro: 'Each of these four is a real problem. Ask which one would still exist if the other three were fixed.', tags: ['Injection', 'sqli'] },
  { q: 'The primary defense against SQL injection is:', opts: ['Escaping quotes in the input before building the query string', 'Binding user values as parameters so the query text is fixed in advance', 'Rejecting any input that contains SQL keywords', 'Running the application\'s queries as a read-only database user'], a: 1, e: 'A prepared statement sends the query text to the database ahead of the values, so the parser has already fixed the structure and a value can never become syntax. Manual escaping and keyword blocklists both leave the input inside the query string and fail on encodings, numeric contexts and dialect differences. A read-only account limits the damage without preventing the injection. One caveat worth carrying: parameters bind values, not identifiers, so a table or column name that comes from user input still needs an allow-list.', intro: 'Ask which of these would still hold if the input arrived in an encoding you did not anticipate.', tags: ['Injection', 'parameterized'] },
  { q: "An input like ' OR '1'='1 in a vulnerable login is an attempt to:", opts: ['Overflow the input field so the password check is skipped', 'Close the quoted string and add a condition that is always true', 'Send an encoding the database driver cannot decode', 'Slow the query enough to leak information through response timing'], a: 1, e: 'The leading quote closes the string literal the developer opened, and OR \'1\'=\'1 appends a condition true for every row, so the WHERE clause stops filtering on the submitted credentials. Attackers normally add a comment terminator too, because AND binds tighter than OR: without one, a trailing AND password = \'...\' still applies and the bypass fails. Timing-based extraction is a separate technique for when the response body reveals nothing, and nothing here overflows a buffer or re-encodes anything.', intro: 'Write out the WHERE clause with this text substituted in, then read it as the database would.', tags: ['Injection', 'example'] },
  { q: 'Injection vulnerabilities are not limited to SQL; they also affect:', opts: ['Shell commands, LDAP filters, NoSQL queries and template engines', 'Other database engines, but only those that speak a SQL dialect', 'Client-side code only, since the browser parses whatever it is given', 'Only interpreters that lack a prepared-statement API of their own'], a: 0, e: 'The pattern is an interpreter: wherever a string is assembled and then parsed - a shell, an LDAP filter, a NoSQL query document, a template or expression evaluator, an XML parser - untrusted input mixed into that string can become instructions instead of data. The remedy has the same shape everywhere: hand the data over through a channel the interpreter cannot mistake for code, such as an argument array for a process or a bound parameter for a query. Whether a prepared-statement API happens to exist changes how you apply that fix, not whether the category applies.', intro: 'Ask what a SQL database actually does with the query string, then look for anything else that does the same.', tags: ['Injection', 'general'] },
  { q: 'An ORM helps reduce SQLi risk because:', opts: ['It parameterizes the queries it generates instead of concatenating strings', 'It validates every field against the schema before the query runs', 'It escapes dangerous characters in the input while mapping objects', 'It runs queries under a restricted database role by default'], a: 0, e: 'An ORM binds values as parameters in the SQL it generates, so ordinary finder and filter calls cannot be turned into new syntax. It does not achieve that by escaping characters or by validating against the schema, and it does not change the database role you connect as. The exception is the escape hatch every ORM offers: raw or literal query fragments are string concatenation again, and interpolating user input into one reintroduces exactly the flaw the ORM was avoiding.', intro: 'Ask what the ORM does with your values when it builds the statement, not what it does with your objects.', tags: ['Injection', 'orm'] },
  { q: 'Input validation (allow-listing) complements parameterization by:', opts: ['Replacing parameterization once the allow-list is strict enough', 'Rejecting clearly invalid input early, as an additional layer', 'Encrypting the input before it reaches the database', 'Guaranteeing that no injection payload can ever reach the query'], a: 1, e: 'Allow-list validation rejects input that could never be legitimate, which shrinks the attack surface and catches mistakes made elsewhere in the stack - but it cannot guarantee that no payload gets through, because legitimate values contain quotes and keywords too, so parameterized queries stay the primary defense. It is a layer, not a replacement. The one place validation is not optional is identifiers: a table, column or sort direction that comes from user input cannot be bound as a parameter and has to be checked against a fixed list.', intro: 'Ask what validation catches that has nothing to do with SQL at all.', tags: ['Injection', 'validation'] },
  { q: 'Command injection happens when:', opts: ['A program is started with an argument array built from user input', 'User input is interpolated into a string that a shell then parses', 'A child process inherits the parent\'s environment variables', 'A command writes its output to a file path the user chose'], a: 1, e: 'Command injection needs a shell: once input is concatenated into a command string that /bin/sh parses, characters such as ; | and $( ) stop being data and become new commands. Handing an argument array to execFile or spawn without shell:true passes the input to the program as one argument, where those characters are inert - that is the fix, not the flaw. Letting a user choose an output path is path traversal and inherited environment variables are a secrets-exposure concern; both are real problems, and neither is command injection.', intro: 'Ask where a semicolon in the input would have to be read for it to start a second command.', tags: ['Injection', 'command'] },
  { q: 'Showing raw database error details to users can:', opts: ['Speed up debugging enough to justify the exposure', 'Reveal table, column and query structure that helps an attacker', 'Prevent injection, by showing which query the database rejected', 'Satisfy logging requirements without a separate log store'], a: 1, e: 'A raw database error names tables, columns, types and often the failing statement, which is precisely the map that turns a blind probe into a working payload - error-based SQL injection is built on this feedback loop. Return a generic message plus a request id and keep the detail in the server log, which preserves the debugging value without publishing it. Showing the error prevents nothing, and an HTTP response is not a log store.', intro: 'Read the message as the attacker would. Ask what it tells them that they did not already know.', tags: ['Injection', 'errors'] },

  // Level 8 — XSS
  { q: 'Cross-site scripting (XSS) is when:', opts: ['A script from your page runs on another site\'s origin', 'Attacker-controlled script runs on your origin in another user\'s browser', 'A user submits a script tag that the server rejects and logs', 'An attacker reads your JavaScript source from the served bundle'], a: 1, e: 'XSS is execution in the victim\'s browser under your origin, so the injected script inherits the page\'s cookies, storage and same-origin access and can act as that user. The direction matters: script escaping to another site\'s origin is what the same-origin policy prevents, and reading your public bundle is not an attack at all. Input the server rejects is a blocked attempt, not a vulnerability.', intro: 'Ask what the injected script can reach once it is running inside your page.', tags: ['XSS', 'basics'] },
  { q: 'Stored (persistent) XSS differs from reflected XSS because the payload is:', opts: ['Delivered in the request and echoed back to that one requester', 'Saved on the server and served to everyone who loads the page', 'Executed only when the victim has JavaScript disabled', 'Written into the database schema rather than into a table row'], a: 1, e: 'In stored XSS the payload is persisted - a comment, a profile field, a filename - and served to every user who loads the affected view, so one submission reaches many victims and keeps working until the records are cleaned. Reflected XSS lives in a request the victim must be induced to send, usually a crafted link, so each victim needs their own delivery. The distinction drives the response: stored means find and purge the stored records as well as fix the sink, reflected means fix the echo. Neither depends on JavaScript being disabled, and neither touches the schema.', intro: 'One payload arrives with each victim\'s own request. Ask where the other one waits.', tags: ['XSS', 'types'] },
  { q: 'The main defense against XSS is:', opts: ['A Content Security Policy that blocks inline script', 'Encoding untrusted data for the context it is rendered into', 'A server-side filter that strips script tags from every input', 'A web application firewall placed in front of the application'], a: 1, e: 'Untrusted data has to be encoded for the context it lands in - HTML text, an attribute, a URL, a script block - because the same characters mean different things in each, and applying the wrong encoding reintroduces the hole. In practice that work belongs to the framework: modern templating escapes by default, which is why OWASP now puts framework auto-escaping first and treats hand-written encoding as the fallback. A CSP is a valuable second layer, but OWASP explicitly warns against relying on it as the primary mechanism, and input filters and firewalls both try to recognize attacks by pattern, which fresh payloads and alternate encodings get past.', intro: 'Ask at which moment the data stops being dangerous: when it arrives, or when it is written into the page.', tags: ['XSS', 'encoding'] },
  { q: 'In React, a common way to introduce XSS is:', opts: ['Rendering a user-supplied string as a text child', 'Passing untrusted HTML to dangerouslySetInnerHTML', 'Storing user input in state before rendering it', 'Reading a user-supplied value from props'], a: 1, e: 'React escapes text children and attribute values, so a string containing markup renders as visible characters rather than elements: rendering <img src=x onerror="alert(1)"> as a text child in React 19 produces the escaped &lt;img src=x onerror=&quot;alert(1)&quot;&gt;. dangerouslySetInnerHTML is the intentional opt-out - it inserts the string as markup, so untrusted HTML becomes live elements and event handlers. When HTML genuinely has to be rendered, sanitize it first with a maintained sanitizer such as DOMPurify. State and props only describe where the value came from; neither changes how React renders it.', intro: 'Ask which of these changes how React writes the value into the DOM, rather than where the value came from.', tags: ['XSS', 'react'] },
  { q: 'A Content Security Policy (CSP) helps mitigate XSS by:', opts: ['Escaping user input before it is written into the page', 'Stripping script tags out of stored user content on the server', 'Restricting which script sources the browser will execute or load', 'Encrypting the response so injected markup cannot be read'], a: 2, e: 'CSP arrives as a response header and tells the browser which script sources may execute, so script injected from an unlisted source, or an inline script without the right nonce or hash, is blocked. Escaping and server-side stripping act on the data instead; CSP acts on execution. OWASP treats CSP as a second layer on top of output encoding, not a replacement for it, so a page with CSP still needs correct escaping.', intro: 'CSP is delivered as a response header, so whatever it does happens in the browser at page load, not in your storage or your templates.', tags: ['XSS', 'csp'] },
  { q: 'Your app has to display rich HTML that users author, such as a formatted comment. Sanitizing that HTML with a library like DOMPurify is the right control because:', opts: ['Escaping it as text would render the same formatting anyway', 'It removes scripts, event-handler attributes, and dangerous URLs while keeping allowed markup', 'It encodes the markup so the browser stores it more compactly', 'It checks that the HTML parses, and well-formed HTML cannot inject'], a: 1, e: 'When the requirement is to render user-authored markup, escaping is off the table, so an allowlist sanitizer keeps the formatting tags and drops scripts, on* handler attributes, and javascript: URLs. Well-formedness is not safety: a perfectly valid document can still carry an onerror handler, which is why the parsing option is wrong. If you only ever show plain text, escape it and skip the sanitizer entirely.', intro: 'Valid markup and safe markup are not the same thing. Think about which attributes and URL schemes can carry behavior, not just which tags.', tags: ['XSS', 'sanitize'] },
  { q: 'XSS can lead to:', opts: ['Reading files from the victim\'s local disk', 'Decrypting the site\'s TLS traffic in transit', 'Acting as the victim inside the page and sending authenticated requests', 'Running attacker code on the web server that served the page'], a: 2, e: 'Injected script runs with the page\'s origin, so it reaches whatever that origin reaches: the DOM, same-origin storage, cookies not marked HttpOnly, and any request that will carry the victim\'s session. It does not touch the local filesystem, does not break TLS (the connection is already decrypted in the browser), and does not execute on the server, so treating XSS as merely cosmetic understates it while treating it as server compromise overstates it.', intro: 'Injected script executes with the page\'s origin. Ask what that origin can already reach in the browser.', tags: ['XSS', 'impact'] },
  { q: 'Escaping data correctly requires knowing:', opts: ['The database column type the value was read from', 'The character encoding the browser negotiated for the response', 'Where the value lands: HTML body, attribute, JavaScript, or URL', 'Whether the value was validated when it was first submitted'], a: 2, e: 'Each sink has its own grammar, so each needs its own encoder: HTML-entity encoding in a text node, attribute encoding inside a quoted attribute, JavaScript string escaping inside a script, and percent-encoding in a URL. Input validation is useful but cannot pick the encoder, because one stored value may later be written into several contexts. HTML-escaping a value that ends up inside a script string leaves the injection point wide open.', intro: 'The same stored value can be safe in one place on the page and dangerous in another. What decides which encoder you owe it?', tags: ['XSS', 'context'] },

  // Level 9 — CSRF
  { q: 'Cross-Site Request Forgery (CSRF) tricks a user into:', opts: ['Revealing their password on a look-alike login page', 'Sending a request to your site that their browser authenticates for them', 'Running attacker script inside your site\'s origin', 'Installing a browser extension that reads their session'], a: 1, e: 'In CSRF the attacker\'s page causes the victim\'s browser to issue a request to your site, and the browser attaches the victim\'s cookies, so your server sees a fully authenticated request the user never meant to make. Phishing takes the credential instead, and XSS runs script inside your origin, which is a strictly larger capability. CSRF needs neither: the attacker never sees your response and never learns the session value.', intro: 'The victim is already logged in, and the attacker never gets to see your site\'s response. Ask what an attacker can still cause to happen.', tags: ['CSRF', 'basics'] },
  { q: 'CSRF exists as a class of bug largely because browsers:', opts: ['Send every cookie they hold to every site a page contacts', 'Let a page read the cookies that belong to another origin', 'Attach a site\'s own cookies to requests aimed at it, including requests another site started', 'Run scripts from any origin unless a Content-Security-Policy is set'], a: 2, e: 'Ambient authority is the root cause: the browser attaches the cookie based on where the request is going, not on who started it, so a forged request still arrives authenticated. A page can never read another origin\'s cookies, which is exactly why the attacker forges a request instead of stealing the value. SameSite=Lax, which several browsers now apply when the attribute is absent, narrows this to top-level navigations using safe methods but does not remove it.', intro: 'The attacker never holds the victim\'s session cookie. Ask what rule the browser uses to decide whether a cookie goes out at all.', tags: ['CSRF', 'why'] },
  { q: 'A primary CSRF defense is:', opts: ['A random token the server issues and re-checks, which the attacker\'s page cannot read', 'Requiring the user to re-enter their password on every write', 'Rejecting requests whose User-Agent header is unfamiliar', 'Setting a long expiry on the session cookie'], a: 0, e: 'The synchronizer token pattern gives each session, or each request, an unpredictable value that the server stores and compares on every state-changing request; the attacker\'s page cannot read it because the same-origin policy blocks reading your responses. Re-authentication would work but is unusable on every write, and User-Agent is attacker-controlled so it proves nothing. OWASP still lists the synchronizer token as the primary defense, with SameSite layered underneath.', intro: 'A forged request already carries everything the browser attaches on its own. Ask what a defense has to add that the browser will not attach for it.', tags: ['CSRF', 'token'] },
  { q: 'The SameSite cookie attribute mitigates CSRF by:', opts: ['Encrypting the cookie value so a cross-site page cannot read it', 'Telling the browser not to attach the cookie to cross-site requests', 'Blocking cross-origin requests to your server outright', 'Requiring that the cookie be sent only over HTTPS'], a: 1, e: 'SameSite tells the browser to withhold the cookie on cross-site requests: Strict on all of them, Lax on all but top-level navigations that use a safe method. That strips away the ambient authority CSRF depends on for most requests. Sending only over HTTPS is the separate Secure attribute, and no cookie attribute blocks the request itself. OWASP treats SameSite as defense in depth rather than a replacement for a CSRF token, because it is scoped to the registrable domain and browser defaults are not uniform.', intro: 'This is one attribute on a Set-Cookie line. Ask what a cookie attribute is able to control, and what it cannot.', tags: ['CSRF', 'samesite'] },
  { q: 'CSRF primarily targets:', opts: ['Requests that only read data, because those return the most information', 'Static assets such as images and stylesheets', 'Any request that changes state, including a GET that was written to change state', 'Requests that carry a bearer token in an Authorization header'], a: 2, e: 'The same-origin policy stops the attacker\'s page from reading your response, so the payoff is the side effect: a transfer, a delete, a settings change. That is why protection belongs on every state-changing endpoint, and why a GET written to mutate state is a CSRF target despite the method being nominally safe. Bearer tokens are not attached by the browser on their own, so those requests are not classic CSRF targets.', intro: 'The attacker never gets to see your response. Ask what a forged request is still worth when the answer is invisible.', tags: ['CSRF', 'targets'] },
  { q: 'APIs using a bearer token in an Authorization header (not cookies) are:', opts: ['More exposed to CSRF, because a header is easier to forge than a cookie', 'Largely outside classic CSRF, because the browser does not attach the token on its own', 'Exposed to CSRF exactly as much as a cookie session is', 'Safe from both CSRF and XSS, because no cookie is involved'], a: 1, e: 'Classic CSRF rides on credentials the browser attaches automatically; a bearer token is added by your own JavaScript, so an attacker\'s page cannot make the browser send it, and a cross-origin request carrying Authorization is not a simple request, so it is preflighted. This trades one risk for another rather than removing risk: a token your JavaScript can read is readable by any injected script too, which is why the last option is wrong.', intro: 'Compare how a cookie gets onto a request with how an Authorization header does. The difference decides which of these still applies.', tags: ['CSRF', 'tokens'] },
  { q: 'A "double submit cookie" CSRF defense works by:', opts: ['Submitting the form twice so the server can compare the two bodies', 'Sending the same token as a cookie and as a request value, then checking that they match', 'Storing two session identifiers and rotating between them', 'Encrypting the request URL so the endpoint cannot be guessed'], a: 1, e: 'The server issues a token as a cookie and expects the same value echoed back in a form field or header, so an attacker\'s page, which cannot read your cookie, cannot supply the matching value. It is the stateless alternative to the synchronizer token. OWASP now warns that this naive form is bypassable by anyone able to write a cookie on your domain, for example through a vulnerable sibling subdomain, and recommends the signed variant that binds the token to the session with an HMAC.', intro: 'This is the stateless option: the server keeps no token of its own. Ask what that forces the request itself to supply.', tags: ['CSRF', 'double-submit'] },
  { q: 'Validating the Origin/Referer header can help against CSRF by:', opts: ['Encrypting the request so its source cannot be forged', 'Rejecting state-changing requests whose stated origin is not your own', 'Preventing the browser from sending cookies to other sites', 'Proving a person, not a script, issued the request'], a: 1, e: 'Origin and Referer are forbidden headers: the browser sets them and page script cannot change them, so on a state-changing request the server can compare the stated origin against its own and reject a mismatch. It is a supporting check rather than a replacement for a token, because a small share of legitimate traffic omits both for privacy reasons and you have to decide what a missing value means. It reveals nothing about whether a person or a script sent the request, and it does not change which cookies the browser attaches.', intro: 'Both headers are set by the browser and page script cannot override them. What can a server therefore trust them to reveal?', tags: ['CSRF', 'origin'] },

  // Level 10 — OWASP Top 10
  { q: 'The OWASP Top 10 is:', opts: ['A ranked awareness document naming the most critical web application security risks', 'A verification standard listing requirements an application must meet to be certified', 'A ranked list of the most dangerous software weaknesses overall, maintained by MITRE', 'A scanner that tests a running application against a fixed set of payloads'], a: 0, e: 'The Top 10 is an awareness document: OWASP periodically re-derives a ranking of broad risk categories from contributed data and a community survey, most recently in the 2025 edition. The requirements standard is OWASP ASVS, which you can actually test an application against, and the ranked weakness list maintained by MITRE is the CWE Top 25, a different artifact with a wider scope. None of the three is a tool, so reaching for the right document depends on knowing which is which.', intro: 'Ask what you would actually do with each of these: read it to learn what to worry about, test an application against it, or run it.', tags: ['OWASP', 'overview'] },
  { q: 'In the OWASP Top 10:2025, the top-ranked risk category is:', opts: ['Injection', 'Security Misconfiguration', 'Broken Access Control', 'Cryptographic Failures'], a: 2, e: 'Broken Access Control is A01 in both the 2021 and the 2025 editions. The rank comes from a risk equation, not from incidence alone: OWASP weights how often a category\'s CWEs appear in contributed test data by the exploitability and impact of the CVEs mapped to them, and this category carries 40 CWEs. Security Misconfiguration rose to A02 in 2025, Cryptographic Failures sits at A04, and Injection fell to A05 as parameterized queries became the framework default. Positions move between editions, so name the edition whenever you cite a rank.', intro: 'The top spot did not change between the 2021 and the 2025 editions, even though most of the other categories moved.', tags: ['OWASP', 'access-control'] },
  { q: '"Cryptographic Failures" (formerly Sensitive Data Exposure) involve:', opts: ['Any use of encryption slower than it needs to be', 'Sensitive data left unprotected: missing encryption, a broken algorithm, or keys handled badly', 'A reported vulnerability in the cryptographic library you depend on', 'Releases published without signatures, so consumers cannot verify them'], a: 1, e: 'Cryptographic Failures, still a category in the 2025 edition at A04, covers sensitive data that is not protected as it should be: sent or stored in the clear, protected with a broken algorithm, or protected with keys that are hardcoded or shared. A published vulnerability in a crypto library falls under Software Supply Chain Failures, and unsigned releases fall under Software or Data Integrity Failures. The category was called Sensitive Data Exposure until 2021, when it was renamed to name the cause instead of the symptom.', intro: 'A vulnerability announced in a library you use has a category of its own. Ask what that leaves this category to cover.', tags: ['OWASP', 'crypto'] },
  { q: '"Security Misconfiguration" includes things like:', opts: ['A missing authorization check on an admin route', 'A SQL query assembled by string concatenation', 'Default credentials, verbose error pages, and unused features left switched on', 'A dependency shipping with a published CVE'], a: 2, e: 'Security Misconfiguration, A02 in the 2025 edition, is about the deployed configuration: shipped default accounts, debug or verbose errors reaching users, over-permissive storage, and features nobody uses left enabled. A missing authorization check is Broken Access Control, a concatenated query is Injection, and a vulnerable dependency is Software Supply Chain Failures. Filing a finding in the right category matters because the fix and its owner differ in each case.', intro: 'Sort each option by who fixes it: the developer editing code, the maintainer upgrading a package, or the person who deployed the service.', tags: ['OWASP', 'misconfig'] },
  { q: 'The OWASP Top 10:2025 expanded \'Vulnerable and Outdated Components\' into \'Software Supply Chain Failures\'. The newer category is broader because it also covers:', opts: ['Compromise of build systems, registries and distribution channels', 'Any bug found in a library, whether or not it has security impact', 'Components written in memory-unsafe languages', 'Dependencies whose licenses conflict with your product'], a: 0, e: 'The 2021 category was about whether your declared dependencies were patched. The 2025 category keeps that and adds the rest of the path the code travels, so a poisoned build server, a hijacked registry account, or a tampered published artifact counts even when every version you declared is current. License conflicts and language choice are real concerns but are tracked elsewhere, and a non-security bug is not a supply-chain failure.', intro: 'The old name asked one question: is this version patched? Ask what that question cannot catch.', tags: ['OWASP', 'components'] },
  { q: 'Which of these describes Server-Side Request Forgery (SSRF)?', opts: ['A client-side script sending requests to its own origin in a loop', 'A server fetching a user-supplied URL, giving the attacker reach to hosts only the server can see', 'An attacker replaying a captured request against the server later', 'A server accepting requests from an origin it never meant to allow'], a: 1, e: 'In SSRF the application takes a URL from the user and fetches it, so the attacker borrows the server\'s network position to reach internal services, admin interfaces, or cloud instance metadata endpoints that are unreachable from the internet. Replaying a captured request is a different attack, and accepting requests from an unintended origin is a CORS or access-control problem. The 2025 edition folded SSRF into Broken Access Control rather than listing it separately, which does not make it any less common.', intro: 'Compare it with CSRF, where the victim\'s browser sends the request. Ask what is different when the request leaves your own server.', tags: ['OWASP', 'ssrf'] },
  { q: 'The OWASP category now called \'Authentication Failures\', renamed from \'Identification and Authentication Failures\' in the 2025 edition, covers:', opts: ['Weak or reused credentials, broken session handling, and no defense against automated guessing', 'Users who authenticate correctly but then reach records belonging to someone else', 'Login forms served without a CSRF token', 'Login responses slow enough that users abandon the form'], a: 0, e: 'This category is about establishing and holding identity: credentials that are guessable or reused, session identifiers that never rotate or expire, and endpoints with no rate limiting or lockout against credential stuffing. Reaching another user\'s records after a successful login is Broken Access Control, a separate and higher-ranked category, and that boundary decides who owns the fix. The 2025 edition shortened the name to match the weaknesses actually mapped to it.', intro: 'Draw a line at the moment the system establishes who is calling. Some of these failures sit before that line and some after.', tags: ['OWASP', 'authn'] },
  { q: 'A team checks its web application against the OWASP Top 10 and finds no listed issue. What is the right conclusion?', opts: ['The application is proven secure against every relevant threat', 'Only network review remains, because the application risks are now closed', 'Threat modeling can be replaced by re-running this checklist each release', 'It is a useful baseline, but this system still needs its own security work'], a: 3, e: 'The Top 10 is an awareness ranking built from data across many applications, so a clean pass means the common categories were checked, not that your architecture, data flows, dependencies and abuse cases were. Calling the application proven secure overreads a sample-based list, and swapping threat modeling for a fixed checklist discards exactly the part that is specific to your system. Treat it as the baseline you start from.', intro: 'The list is derived from what was common across many applications. Ask what it can therefore say about the risks unique to yours.', tags: ['OWASP', 'usage'] },

  // Level 11 — Secrets Management
  { q: 'API keys, DB passwords, and tokens should be:', opts: ['Hardcoded in source so every environment gets the same value', 'Kept out of the repository and supplied from environment config or a secrets manager', 'Committed to a private repository, since only the team can read it', 'Sent to the client at startup so the browser can call the API directly'], a: 1, e: 'Secrets belong outside the code, injected at runtime from environment configuration or fetched from a manager, so rotating one does not mean editing and redeploying source. A private repository is not a control: every clone, fork, CI log and past commit keeps the value, and visibility settings change. Shipping a secret to the browser makes it public the moment someone opens dev tools. Environment variables are the low end of this: they keep secrets out of git but still surface in process listings, crash dumps and CI output, which is what a manager improves on.', intro: 'Ask who can read the value once it is in place: everyone with repository history, or only the running process.', tags: ['Secrets', 'storage'] },
  { q: 'If a secret is accidentally committed to Git, you should:', opts: ['Delete the commit and force-push, which takes the value out of history', 'Rotate the secret first, treating it as already compromised, then purge it from history', 'Make the repository private, so the value is no longer reachable', 'Add the file to .gitignore so future commits will not include it'], a: 1, e: 'You cannot un-publish a value that was readable, and scanners watching public pushes act within seconds, so the only reliable move is to invalidate the credential itself and clean history afterwards. Force-pushing or switching the repository to private closes the easy path but not existing clones, forks, caches or anything already scraped. Adding the file to .gitignore prevents the next mistake and does nothing about this one.', intro: 'The value was readable by someone for some window. Ask what you can still change about it, and what you can no longer change.', tags: ['Secrets', 'leak'] },
  { q: 'Compared with putting the same values in environment variables, a secrets manager mainly adds:', opts: ['Faster reads, because the value is already loaded in the process', 'Per-identity access control, an audit trail, and rotation without a redeploy', 'Protection even when an attacker already has code execution in your process', 'A guarantee that the secret can never appear in your application logs'], a: 1, e: 'A manager turns a static string into a managed object: access is granted per identity, every read is recorded, and a value can be rolled centrally without shipping a new build. It does not stop an attacker already running code as your service, because that code can request the secret exactly as your application does, and it cannot stop your own code from logging the value once it holds it. Speed is not the benefit either; a manager usually costs a round trip, which is why clients cache.', intro: 'Both approaches keep the value out of git. Ask what stays exactly the same once an attacker is already running code as your service.', tags: ['Secrets', 'manager'] },
  { q: 'Secrets should never be:', opts: ['Encrypted', 'Exposed in client-side code or logs', 'Rotated', 'Access-controlled'], a: 1, e: 'Anything shipped to the browser or written to logs can leak; keep secrets server-side and out of logs.', tags: ['Secrets', 'exposure'] },
  { q: 'Rotating secrets periodically helps by:', opts: ['Making a leaked value useless after a bounded window', 'Preventing the secret from leaking in the first place', 'Removing the need to restrict who may read the secret', 'Proving that nobody else has used the secret'], a: 0, e: 'Rotation bounds exposure: whatever an attacker captured stops working at the next roll, which matters most for the leaks you never find out about. It prevents nothing, replaces no access control on who may read the value, and proves nothing about past use, which is what audit logging is for. It is also the required first step after any suspected exposure, not only a scheduled chore, and its real cost is that your system has to survive a value changing under it.', intro: 'Rotation is not prevention and not detection. Ask what a scheduled change does to a value someone already copied.', tags: ['Secrets', 'rotation'] },
  { q: 'A frontend app needing to call a third-party API with a secret should:', opts: ['Embed the key in the bundle, since the bundle is minified', 'Send the key to the browser once at startup and hold it in memory only', 'Call the third-party API through your own backend, which holds the key server-side', 'Ship the key but restrict it to your domain with an HTTP referrer allowlist'], a: 2, e: 'Route the call through your own endpoint: the browser talks to you, you talk to the third party, and the key never leaves the server, which also gives you one place to authorize, rate-limit and log. Minification is not concealment, and a key held only in memory still crossed the wire, so both of those publish it. Referrer and origin allowlists exist for keys a vendor designed to be public and are trivially spoofed outside a browser, so they cap abuse and spend rather than keeping a secret secret.', intro: 'Referrer and origin checks only exist inside a browser. Ask what a request made from the command line would carry instead.', tags: ['Secrets', 'frontend'] },
  { q: 'Environment-specific secrets (dev vs prod) should be:', opts: ['The same values everywhere, so a bug reproduces identically in every environment', 'Distinct values per environment, so a leak outside production cannot reach production', 'Production values in staging, so staging exercises the real integration', 'One shared value rotated more often, which keeps the exposure window short'], a: 1, e: 'Separate credentials bound the blast radius: a value pasted into a ticket, printed by a debug build, or left in a CI log in staging then buys an attacker nothing in production. Copying production values into staging does the opposite, and realistic integration testing is what a provider\'s sandbox credentials are for. Sharing one value and rotating it faster makes every rotation a coordinated change across all environments, and a single leak still exposes all of them.', intro: 'Count the people and tools that touch a non-production credential. Then ask what you would have to do the day one of them leaks it.', tags: ['Secrets', 'environments'] },
  { q: 'Running an automated secret scanner over your repository and its history mainly helps by:', opts: ['Encrypting any credential it finds, so the commit becomes safe', 'Guaranteeing that no credential can ever be committed', 'Finding credentials in commits and history so they can be rotated and removed', 'Removing the need to keep secrets out of the repository at all'], a: 2, e: 'Scanners match known credential shapes against your commits, so they surface exposures nobody noticed, including old ones buried in history, and a pre-commit or pre-receive hook can catch some before they land. Finding a secret does not neutralize it: the response is still rotate first, then purge. A scanner has no pattern for every format, so it supplements the practice of keeping secrets out of the repository instead of replacing it.', intro: 'A scanner reads what is already there. Ask what it can tell you, and what it still cannot stop.', tags: ['Secrets', 'scanning'] },

  // Level 12 — Secure Defaults & Headers
  { q: 'Secure defaults mean:', opts: ['The system ships locked down, and loosening it takes a deliberate opt-in', 'The system ships with every feature enabled so nothing is unexpectedly blocked', 'The system needs no configuration at all before it is deployed', 'The system warns the operator about risky settings but applies them anyway'], a: 0, e: 'Secure by default means the safe configuration is what you get when nobody intervenes, so a rushed deployment is still safe and every relaxation is a deliberate, reviewable choice. Shipping permissive and warning about it moves the burden onto an operator who may never read the warning, which is how default credentials and world-readable buckets reach production. It is not the same as needing no configuration: a secure default can still require you to supply a key or a hostname.', intro: 'Ask what is in force when nobody reads the hardening guide. That configuration is the default.', tags: ['Headers', 'defaults'] },
  { q: 'The Content-Security-Policy header primarily mitigates:', opts: ['SQL injection, by filtering query parameters before they reach the database', 'Protocol downgrade, by refusing to serve the page over plain HTTP', 'Cross-site scripting and other content injection, by limiting what the browser may load and execute', 'Cross-site request forgery, by rejecting requests that originate on another site'], a: 2, e: 'CSP is a browser-enforced policy over the page it arrived with, so it constrains which scripts, styles, frames and connections are permitted, and that is what limits the damage of injected content. SQL injection is settled in the data layer, and the HTTPS-only rule is Strict-Transport-Security. CSP does touch CSRF at the edges through form-action and frame-ancestors, but it does not replace a CSRF token, and OWASP treats CSP itself as a second layer on top of correct output encoding.', intro: 'CSP is enforced by the browser on the response it received. Ask which of these attacks is decided in the browser and which on the server.', tags: ['Headers', 'csp'] },
  { q: 'X-Content-Type-Options: nosniff prevents:', opts: ['Cross-site requests from ever reaching your server', 'The browser from guessing a response\'s type and treating it as script or CSS', 'Scripts hosted on other origins from being loaded at all', 'Users from downloading files the server did not mean to serve'], a: 1, e: 'With nosniff the browser takes the declared Content-Type at face value: a response labeled text/plain is blocked when a script tag requests it, and a stylesheet must genuinely be text/css. That matters most for user-uploaded content, where a file the server labels text/plain would otherwise be sniffed into HTML or JavaScript and executed inside your origin. It says nothing about which origins may load a resource, which is what CORS and CSP govern.', intro: 'The header\'s name is the verb it turns off. Ask what a browser does when a response\'s declared type and its content disagree.', tags: ['Headers', 'nosniff'] },
  { q: 'The Strict-Transport-Security header enforces:', opts: ['That the browser use HTTPS for this host and refuse to let the user click past certificate errors', 'That the server reject any request arriving over plain HTTP', 'That every subresource on the page be upgraded to HTTPS before loading', 'That the connection negotiate the newest TLS version both sides support'], a: 0, e: 'HSTS tells the browser to reach this host over HTTPS for max-age seconds and to make certificate warnings non-bypassable, so a later http:// link or a stripped redirect never leaves the browser in plaintext. It is trust on first use: the request made before any HSTS response was seen is still exposed, which is what the preload list exists to close, and browsers ignore the header when it arrives over plain HTTP. Upgrading mixed subresources is CSP\'s upgrade-insecure-requests, and the negotiated TLS version is settled in the handshake, not by a header.', intro: 'The header is an instruction the browser remembers for a set time. Ask what the browser does differently on the next visit.', tags: ['Headers', 'hsts'] },
  { q: 'Running an app in debug mode in production is risky because it can:', opts: ['Slow request handling enough to enable a denial of service', 'Reveal stack traces and configuration values to anyone who triggers an error', 'Switch off the framework\'s built-in input validation', 'Prevent log rotation and fill the disk'], a: 1, e: 'A debug error page is built for a developer, so it prints stack frames, framework and library versions, file paths, route tables and often environment or connection settings; in production an attacker collects all of that for the price of one malformed request. Debug mode does cost performance and does fill logs, but neither is why it is a security finding. It does not disable validation, so the risk is disclosure rather than a new injection point.', intro: 'Debug mode changes what happens when something goes wrong. Ask who can make something go wrong on a public server.', tags: ['Headers', 'debug'] },
  { q: 'Why are default credentials like admin/admin such a serious risk?', opts: ['They are publicly documented and attackers scan for them continuously', 'They expire quickly and lock administrators out of the system', 'They are stored with a weaker hash than credentials users choose', 'They only matter on systems that are reachable from the internet'], a: 0, e: 'Default credentials appear in vendor documentation and in public lists, so they cost an attacker nothing to obtain and scanners try them across whole address ranges continuously. The weakness is that the value is known, not how it is stored, so hashing a published password strongly protects nothing. Treating internal systems as out of reach ignores that one compromised workstation or VPN session puts the attacker on that network.', intro: 'Ask whether an attacker has to guess anything here, and whether being off the public internet is the same as being unreachable.', tags: ['Headers', 'defaults'] },
  { q: 'CORS misconfiguration (e.g. reflecting any Origin with credentials) can:', opts: ['Let any site send a simple GET to your API that it could not send before', 'Let a malicious site read your API\'s authenticated responses in the victim\'s browser', 'Expose your API to requests that carry no Origin header', 'Turn off the same-origin policy for every site the user visits'], a: 1, e: 'Simple cross-origin requests were always sendable; what the same-origin policy withholds is the response. Reflecting the caller\'s Origin and adding Access-Control-Allow-Credentials tells the browser to hand that authenticated response to the calling page, so any site the victim visits can read their data. It does not switch off the same-origin policy globally, and requests without an Origin are not the problem. This is why you allow an explicit list of origins, and why the wildcard is rejected outright when credentials are involved.', intro: 'The victim\'s cookies were already going along. Ask what an attacker\'s page gains that it did not have before.', tags: ['Headers', 'cors'] },
  { q: 'A service still exposes a /v1 API that nothing calls any more, and serves directory listings from its static folder. Removing both is worth doing because:', opts: ['It removes code and paths an attacker can probe, and stops the listing advertising what is there', 'It makes the remaining endpoints respond faster under load', 'It satisfies a rule that a service must expose exactly one API version', 'It is the only way to stop unauthenticated access to those paths'], a: 0, e: 'Every reachable endpoint is code that has to stay patched and reviewed, and an endpoint nobody calls rarely gets either, while a directory listing gives an attacker a file map they would otherwise have to guess. Removing both shrinks what can be probed and what can be learned. Authentication could also protect those paths, so removal is not the only option; it is the one that eliminates the exposure instead of guarding it.', intro: 'Neither of these is anyone\'s job any more. Ask what that costs you the first time someone else goes looking.', tags: ['Headers', 'hardening'] },

  // Level 13 — Dependency & Supply Chain
  { q: 'A software supply chain attack compromises:', opts: ['Only the code your own team wrote and reviewed', 'A dependency, a build system, or a distribution channel', 'The physical hardware in the datacenter where your service runs', 'The network path between your users and your servers'], a: 1, e: 'A supply-chain attack works by reach: compromise one widely used package, one build server or one publishing account, and the malicious code is installed by everyone who trusts it, usually through the normal signed channels. Hardware and network attacks are real but reach only the systems they touch. This breadth is why the 2025 OWASP Top 10 raised the category to A03 and widened it past dependency versions to build and distribution infrastructure.', intro: 'You install and trust some of these on purpose and never see the others. Ask which one arrives through a channel you already trust.', tags: ['Supply Chain', 'basics'] },
  { q: 'A library your service depends on has a published security advisory. Which reasoning best supports upgrading promptly?', opts: ['A newer release is always more stable than the one it replaces', 'The advisory is public, so the weakness is known and your current version stays exposed until you move', 'Upgrading resets the dependency\'s age, which scanners score on', 'Maintainers stop answering issues filed against older versions'], a: 1, e: 'Once an advisory is published, the weakness and often a working proof of concept are public, so the balance tips: staying put is a known, scannable exposure while upgrading carries ordinary change risk that tests can cover. Newer is not automatically more stable, which is why you still read the changelog and pin through a lockfile. Scanner scores and maintainer attention are side effects, not reasons.', intro: 'Weigh the two risks against each other: the one you take by upgrading, and the one you keep by not upgrading.', tags: ['Supply Chain', 'updates'] },
  { q: 'A lockfile (e.g. package-lock.json) improves supply-chain safety by:', opts: ['Recording the exact resolved version and integrity hash of every package, direct and transitive', 'Guaranteeing that no package in the tree can ever be published with a vulnerability', 'Restricting the project to packages from a single trusted publisher', 'Removing the need to review dependency updates, since versions cannot change'], a: 0, e: 'A lockfile records the exact version and an integrity hash for every package in the tree, transitive ones included, so a later install reproduces the same bytes instead of re-resolving a range to whatever is newest. That is what turns an upgrade into a reviewable diff rather than a silent change between two installs. It does not vet anything: pinning a compromised version pins the compromise, which is exactly why lockfile changes belong in code review.', intro: 'Ask what could differ between two installs of the same project a month apart, on two different machines.', tags: ['Supply Chain', 'lockfile'] },
  { q: 'Tools like npm audit / Dependabot help by:', opts: ['Proving that a flagged package is actually exploitable in your application', 'Matching your installed versions against published advisories and reporting what matches', 'Rewriting your code so it stops calling the vulnerable function', 'Blocking any install that would add a new transitive dependency'], a: 1, e: 'They compare the versions recorded in your lockfile against a database of published advisories and report the matches, and Dependabot can open the upgrade pull request for you. What they cannot tell you is whether your code ever reaches the vulnerable path, which is why a long audit report needs triage rather than a blanket upgrade or a blanket ignore. They neither prove exploitability nor touch your code.', intro: 'Ask what evidence these tools actually work from, and whether any of it says anything about your own call sites.', tags: ['Supply Chain', 'scanning'] },
  { q: 'Typosquatting in package registries refers to:', opts: ['Publishing a package whose name resembles a popular one, so a typo installs the attacker\'s code', 'Publishing a package under a name an organization uses privately, so the public one wins resolution', 'Taking over a package whose maintainer account was abandoned', 'Republishing an existing package under a higher version number without changes'], a: 0, e: 'Typosquatting rides on the name alone: a package called reqeusts or crossenv sits in the registry waiting for a mistyped install command or a copied README, and its install script then runs with the developer\'s privileges. Dependency confusion is the adjacent attack where a public name shadows a private one, and maintainer-account takeover compromises a package you deliberately chose. Reading the name character by character before adding it, and pinning through a lockfile, is what defends against the first.', intro: 'Nothing about the code is wrong here; the name is. Ask what makes a developer install the wrong package without noticing.', tags: ['Supply Chain', 'typosquatting'] },
  { q: 'Pulling unpinned Docker base images (e.g. :latest) is risky because:', opts: ['The tag can be reassigned to a different image at any time', 'Docker refuses to cache images pulled by a floating tag, which slows every build', 'The tag always resolves to the newest release, and newest is always the most secure', 'Images pulled by tag skip the signature checks that digest pulls perform'], a: 0, e: 'A tag is a mutable pointer: the publisher can move :latest to a different image whenever they like, so the same Dockerfile can produce different contents on different days and the build you tested is not necessarily the build you ship. Pinning to a digest makes the reference content-addressed, so the pull either matches those bytes or fails, and upgrades become deliberate. Newest is not automatically safest, and caching is not what breaks here.', intro: 'Ask what guarantees you have that a rebuild three months from now pulls the same bytes you tested.', tags: ['Supply Chain', 'images'] },
  { q: 'A vulnerability is disclosed in a widely used library. An SBOM helps you because it:', opts: ['Lists every component and version that went into your build', 'Blocks the vulnerable component from being installed in future builds', 'Records who approved each dependency and when', 'Proves the build has not been tampered with since it was published'], a: 0, e: 'An SBOM is the inventory of what actually went into a build, component by component and version by version, so \'are we affected\' becomes a lookup instead of an archaeology exercise across repositories and images. It is a record, not a control: it blocks nothing and authorizes nothing. Tamper-evidence comes from signing and attestation, which are related supply-chain practices but a different artifact with a different purpose.', intro: 'Ask what you would otherwise have to do to answer that question across every repository and image you ship.', tags: ['Supply Chain', 'sbom'] },
  { q: 'A pull request replaces a four-line helper with a new dependency. The security-relevant argument against merging it is:', opts: ['The dependency and everything it pulls in becomes code you must trust, patch and monitor', 'Any added dependency increases bundle size, which browsers penalize', 'Third-party code is inherently less correct than code you write yourself', 'A dependency cannot be audited, because you did not write it'], a: 0, e: 'Adding a package adopts its whole transitive tree as code you must trust, keep patched and watch for advisories, and replacing four lines is exactly where that ongoing cost buys the least. It is not an argument for writing everything yourself: a mature library for parsing, crypto or dates is usually safer than a hand-rolled version, so the real test is whether the dependency does something you would get wrong. Third-party code is not inherently less correct, and it can be audited.', intro: 'The four lines are not the whole comparison. Ask what else you take on beyond the code you can see in the diff.', tags: ['Supply Chain', 'minimize'] },

  // Level 14 — Data Protection & Privacy
  { q: 'PII (personally identifiable information) includes:', opts: ['Names, emails, addresses and other data that identifies a person', 'Only government-issued identifiers such as passport or national ID numbers', 'Any record held in a production database', 'Only the fields a user has marked as private in their settings'], a: 0, e: 'PII is data that identifies a person, on its own or in combination, so an email address, a home address or a device identifier tied to an account all qualify. Limiting it to official identifiers misses most of what a breach actually exposes, and letting user settings decide would make the obligation depend on a checkbox nobody ticks. Location in a database is not the test either: an aggregate row may not be PII while a single support ticket usually is.', intro: 'Ask what a breach notification would actually have to cover, rather than what a settings screen or a schema says.', tags: ['Privacy', 'pii'] },
  { q: 'Data minimization means:', opts: ['Collecting everything now, in case a future feature needs it', 'Collecting and keeping only what a stated purpose requires, and deleting it when that purpose ends', 'Storing data only in aggregate form, never per user', 'Keeping the data but encrypting it, which removes the need to limit collection'], a: 1, e: 'Minimization limits collection and retention together: you take what a stated purpose needs and delete it when that purpose ends, which is why a retention schedule is part of the control rather than an afterthought. Encryption protects what you hold without reducing what you hold, so a breach still involves records you should already have deleted. Aggregation is one technique rather than the principle, and many legitimate purposes need per-user data.', intro: 'Encryption and aggregation are things you do to data you already hold. Ask what this principle says about holding it at all.', tags: ['Privacy', 'minimization'] },
  { q: 'Encryption at rest protects data by:', opts: ['Making stored data unreadable to anyone who obtains the disk or a backup without the key', 'Making the data unreadable to an attacker who has compromised the running application', 'Preventing a database administrator from querying the table', 'Removing the need to control who may read the data'], a: 0, e: 'Encryption at rest defends against loss of the storage itself, a stolen disk, a decommissioned drive, a copied backup snapshot, because the ciphertext is useless without a key held elsewhere. It does nothing against an attacker who has compromised your running application or a legitimate database session, since both read through the layer that decrypts for them. That is exactly why it is one control among several rather than an answer to \'is our data safe\'.', intro: 'Ask which layer performs the decryption, and who is already on the right side of it.', tags: ['Privacy', 'at-rest'] },
  { q: 'A product is implementing a privacy request workflow. Which capability is relevant to rights found in laws such as GDPR?', opts: ['Keep personal data indefinitely, in case it becomes useful later', 'Publish every user record so people can check the database themselves', 'Let a verified person access, correct, or request erasure of their personal data', 'Replace consent and legal review with a longer privacy policy'], a: 2, e: 'GDPR gives data subjects rights over their own records, including access, rectification and erasure under defined conditions, so the workflow has to identify the requester and act on their data alone. Publishing everyone\'s records would be a breach rather than transparency, and erasure is not absolute, since legal retention duties can override it, which is why identity checks, legal rules and an audit trail belong in the workflow. A longer policy document grants nobody a right.', intro: 'Transparency is not the same as publication, and a policy document is not a right. Ask what a person can actually demand.', tags: ['Privacy', 'gdpr'] },
  { q: 'Masking/redacting sensitive fields in logs prevents:', opts: ['Copies of secrets and personal data spreading into log storage and everything downstream of it', 'Attackers reading the application\'s log files directly on the server', 'Log volume growing faster than the retention policy allows', 'Errors being recorded without enough context to debug them'], a: 0, e: 'A logged password, token or identifier is copied everywhere the log travels: the aggregation service, its backups, the dashboards teams share, and any retention window measured in months. Redacting where the log line is written keeps it out of all of them at once, which is why it belongs in the logger rather than in a cleanup job afterwards. It is not about who can read one file on one server, and done well it keeps enough context to debug, for example by logging a user id instead of an email address.', intro: 'Think past the server where the line was written. Ask what else holds a copy of it a month later.', tags: ['Privacy', 'logging'] },
  { q: 'Pseudonymization differs from anonymization because pseudonymized data:', opts: ['Can never be linked back to a person by anyone', 'Is stored in plaintext, while anonymized data is encrypted', 'Can still be linked back to a person by whoever holds the mapping or the extra data', 'Falls outside data-protection law, while anonymized data does not'], a: 2, e: 'Pseudonymization swaps identifiers for tokens while the mapping survives, so whoever holds it can re-link the records, and the data therefore remains personal data with the obligations that follow. Anonymization only counts as anonymization when re-identification is not reasonably possible for anyone, including by combining the set with other data, which is a far higher bar than replacing a name with an id. The legal consequence runs the opposite way from the last option: it is anonymized data that falls outside the regime.', intro: 'Ask what would have to be true for re-identification to be impossible for everyone, not just for you.', tags: ['Privacy', 'pseudonymization'] },
  { q: 'A data breach response should include:', opts: ['Restore service first, then investigate once the incident has quieted down', 'Contain the access path and preserve evidence, assess scope, notify as required, then fix the cause', 'Rebuild the affected systems immediately, so the attacker loses access', 'Wait until the scope is fully understood before taking any containment action'], a: 1, e: 'Containment comes first and preserves evidence: cut the access path, capture logs, snapshot systems, then establish what was reached, notify whoever law and contracts require within their deadlines, and fix the root cause. Rebuilding at once does evict the attacker but destroys the forensic record, and with it the answer to what was taken, which is exactly what notification depends on. Waiting for a complete picture leaves them inside, and restoring service without finding the entry point usually reintroduces it.', intro: 'One of these instincts destroys the evidence you will need; another leaves the attacker working while you investigate.', tags: ['Privacy', 'breach'] },
  { q: 'Encrypting backups is important because:', opts: ['Backups hold the same data as production but often sit outside its access controls and monitoring', 'Backups are written in a format that is easier to read than the live database', 'Encryption makes restores faster, because less data has to be transferred', 'Encrypting backups removes the need to control who may run a restore'], a: 0, e: 'A backup is a complete copy of production data that often lives in another account, another region or on removable media, with weaker access control and thinner monitoring than the live system, which makes it the easier target. Encrypting it with keys held separately means a copied snapshot is inert. It says nothing about who may run a restore, which needs its own authorization, and encryption does not make restores faster.', intro: 'Ask who can reach a snapshot taken six months ago, and whether anyone would notice them doing it.', tags: ['Privacy', 'backups'] },

  // Level 15 — Secure Design & Threat Modeling
  { q: 'Threat modeling is the practice of:', opts: ['Reviewing a design to identify what is worth attacking, how it could be attacked, and what to build against it', 'Running an automated scanner against the deployed system and triaging its findings', 'Ranking the known CVEs in your dependencies by severity score', 'Testing a running application by attempting the attacks in the OWASP Top 10'], a: 0, e: 'Threat modeling is design-time work: you describe the system and its trust boundaries, ask what an attacker wants and how they could get it, and decide which mitigations to build in. The other three are real activities but each needs something already written or running, so they find implementation flaws rather than design flaws, and design flaws are the expensive kind to discover late. Insecure Design became its own Top 10 category precisely because scanning cannot find what was never designed in.', intro: 'A scanner can only find what was built. Ask which failures never show up as a bug in the code.', tags: ['Design', 'threat-modeling'] },
  { q: 'While threat modeling you notice that the audit log can be edited by the same service account that writes it. In STRIDE, that is an instance of:', opts: ['Repudiation', 'Spoofing', 'Information disclosure', 'Elevation of privilege'], a: 0, e: 'Repudiation is the threat that an actor can deny having done something because the evidence was alterable or never captured, and a log the acting identity can edit is the textbook case; the mitigation is append-only storage or a separate write path. Spoofing is pretending to be another identity, information disclosure is reading what you should not, and elevation of privilege is gaining rights you were not granted. STRIDE earns its place by forcing you past the two or three threats everyone thinks of first.', intro: 'Ask what an attacker gains by changing the record of what happened, rather than by reading it or by becoming someone else.', tags: ['Design', 'stride'] },
  { q: '"Shift left" in security means:', opts: ['Moving security work earlier: threat modeling in design, security review and scanning on the pull request', 'Replacing the security team\'s review with automated checks in CI', 'Handing security to developers so specialists are no longer needed', 'Running the same annual penetration test earlier in the release cycle'], a: 0, e: 'Shifting left attaches security to stages that already exist: threat modeling while the design is still cheap to change, security review and automated scanning on the pull request, so a finding is a code change rather than an incident. It adds rather than substitutes, because automated checks and human review find different things, and developer ownership does not remove the need for people who do this full time. Moving one penetration test earlier just tests an unfinished system.', intro: 'Ask which activities move earlier, and whether moving them earlier means anything gets removed.', tags: ['Design', 'shift-left'] },
  { q: 'Building security into design is cheaper than retrofitting because:', opts: ['It never matters', 'Flaws found early cost far less to fix than after deployment/breach', 'Late fixes are free', 'Design has no impact'], a: 1, e: 'Like all defects, security flaws are far cheaper to address in design than after they ship or cause a breach.', tags: ['Design', 'cost'] },
  { q: 'A secure design principle is to minimize trust by:', opts: ['Authenticating and authorizing calls between your own services, not only at the public edge', 'Placing every service inside one private network so external traffic cannot reach them', 'Validating input once at the edge, so internal services can trust whatever they receive', 'Encrypting internal traffic, which establishes who the caller is'], a: 0, e: 'A trust boundary is anywhere a request crosses from one authority into another, and every crossing needs its own authentication, authorization and validation, service to service included. A private network is a location rather than an identity, so anything that gets inside inherits whatever the perimeter was granting. Validating only at the edge fails the moment a second path writes to the same store, and transport encryption proves the channel is confidential without proving who is on the other end unless the client certificate is verified too.', intro: 'Ask what an attacker who is already inside your network can call, and what would stop them.', tags: ['Design', 'trust-boundaries'] },
  { q: 'Which security-testing plan is the most defensible for a production web service?', opts: ['Manual clicking through the visible interface, since that is what users reach', 'One scheduled annual scan, with findings triaged at the following scan', 'Unit tests written by whoever implemented each feature', 'Code review, automated scanning, dependency checks and focused penetration testing together'], a: 3, e: 'The techniques find different classes of problem: review catches logic and authorization mistakes no scanner models, scanners give cheap repeatable breadth, dependency checks cover code nobody on the team wrote, and penetration testing chains small weaknesses into a real attack path. Relying on one leaves its blind spot uncovered, and unit tests by the implementer inherit the assumptions that produced the bug. An annual scan whose findings wait for the next run is exposure rather than a program.', intro: 'Each of these techniques has a blind spot. Name the blind spot of each one before you choose.', tags: ['Design', 'testing'] },
  { q: 'Logging and monitoring for security helps by:', opts: ['Recording enough detail to detect suspicious activity and reconstruct what happened afterwards', 'Preventing attacks, by making the attacker\'s own actions visible to them', 'Satisfying auditors, which is the main reason to keep security logs', 'Replacing preventive controls, since anything logged can be undone later'], a: 0, e: 'Security logging buys two things prevention cannot: a chance to notice an attack while it is still running, and the record needed afterwards to establish scope, which is what breach notification depends on. It prevents nothing by itself, and that is why the 2025 OWASP category is called Security Logging and Alerting Failures: a log nobody alerts on is a log nobody reads. Audit satisfaction is a by-product, and nothing about logging undoes an action.', intro: 'Logs change nothing about whether an attack succeeds. Ask what they change about what happens next.', tags: ['Design', 'monitoring'] },
  { q: 'A service passed a penetration test six months ago and its code has not changed since. What is the most defensible statement about its security today?', opts: ['It is still secure, because nothing in the code changed', 'Its dependencies, deployed configuration and threat landscape have moved, so the assessment has aged', 'It is insecure, because any assessment older than a month is worthless', 'Nothing can be said until a new penetration test is run'], a: 1, e: 'A point-in-time assessment ages even when the code does not: new advisories land against the same dependency versions, base images and platforms accumulate findings, configuration drifts, and attack techniques improve. That is why security is a continuing process with dependency alerts, configuration review and periodic reassessment rather than a milestone you pass. Both extremes are unusable: an unchanged code base is not automatically fine, and a six-month-old report is still evidence, just evidence with a date on it.', intro: 'Ask what a penetration test report is a statement about, and what date is on it.', tags: ['Design', 'mindset'] },
];
